/* The logger_system system on a PC: every machine on its fake board, one clock, the
 * real router.
 *
 * Usage: build/logger_system_sim [--trace out.sgt] <run_ms> [machine.EVENT[@ms] ...]
 * Each event is posted to that machine (every instance) at its time, 0 by
 * default. The clock moves in 10 ms steps; each step runs every machine once.
 * Log lines print as they happen, then the state of every instance. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "logger_system.h"
#include "../device/src/gen/fake.h"
#include "../sampler/src/gen/fake.h"
#include "../logger/src/gen/fake.h"
#include "../sensor/src/gen/fake.h"

static device_probe_t device_probe;
static sampler_probe_t sampler_probe;
static logger_probe_t logger_probe;
static sensor_probe_t sensor_probe;
static logger_system_system_t sys;

typedef struct {
    const char *name;
    int value;
} named_t;

static const named_t device_events[] = {
    {"BUTTON", DEVICE_EV_BUTTON},
    {"LOG_FULL", DEVICE_EV_LOG_FULL},
    {"FAULT", DEVICE_EV_FAULT},
    {NULL, 0},
};

static const named_t sampler_events[] = {
    {"START", SAMPLER_EV_START},
    {"STOP", SAMPLER_EV_STOP},
    {"PERIOD", SAMPLER_EV_PERIOD},
    {NULL, 0},
};

static const named_t logger_events[] = {
    {"START", LOGGER_EV_START},
    {"STOP", LOGGER_EV_STOP},
    {"TICK", LOGGER_EV_TICK},
    {"DISK_FULL", LOGGER_EV_DISK_FULL},
    {NULL, 0},
};

static const named_t sensor_events[] = {
    {"START", SENSOR_EV_START},
    {"CALIBRATED", SENSOR_EV_CALIBRATED},
    {"CAL_TIMEOUT", SENSOR_EV_CAL_TIMEOUT},
    {NULL, 0},
};

static int lookup(const named_t *t, const char *name) {
    for (; t->name; t++)
        if (!strcmp(t->name, name)) return t->value;
    return -1;
}

static void trace_sink(void *ctx, const uint8_t *record, size_t len) { fwrite(record, 1, len, ctx); }

typedef struct {
    int machine, event;
    uint64_t at;
    int sent;
} plan_t;

static void post(const plan_t *p) {
    switch (p->machine) {
    case 0: logger_system_post_device(&sys, (device_event_t)p->event, NULL, 0); break;
    case 1: logger_system_post_sampler(&sys, (sampler_event_t)p->event, NULL, 0); break;
    case 2: logger_system_post_logger(&sys, (logger_event_t)p->event, NULL, 0); break;
    case 3: logger_system_post_sensor(&sys, (sensor_event_t)p->event, NULL, 0); break;
    }
}

/* Prints what each board logged since the last call, then clears the probes
 * so a long run never fills them. */
static void drain(uint64_t t) {
    for (int i = 0; i < device_probe.n_logs; i++) printf("%8llu ms  device   %s\n", (unsigned long long)t, device_probe.logs[i].msg);
    device_probe.n_logs = device_probe.n_calls = device_probe.n_traces = 0;
    for (int i = 0; i < sampler_probe.n_logs; i++) printf("%8llu ms  sampler  %s\n", (unsigned long long)t, sampler_probe.logs[i].msg);
    sampler_probe.n_logs = sampler_probe.n_calls = sampler_probe.n_traces = 0;
    for (int i = 0; i < logger_probe.n_logs; i++) printf("%8llu ms  logger   %s\n", (unsigned long long)t, logger_probe.logs[i].msg);
    logger_probe.n_logs = logger_probe.n_calls = logger_probe.n_traces = 0;
    for (int i = 0; i < sensor_probe.n_logs; i++) printf("%8llu ms  sensor   %s\n", (unsigned long long)t, sensor_probe.logs[i].msg);
    sensor_probe.n_logs = sensor_probe.n_calls = sensor_probe.n_traces = 0;
}

int main(int argc, char **argv) {
    const char *trace_path = NULL;
    int a = 1;
    if (argc > 2 && !strcmp(argv[1], "--trace")) { trace_path = argv[2]; a = 3; }
    if (a >= argc) {
        fprintf(stderr, "usage: %s [--trace out.sgt] <run_ms> [machine.EVENT[@ms] ...]\n", argv[0]);
        return 2;
    }
    uint64_t run_ms = strtoull(argv[a++], NULL, 10);
    int n = argc - a;
    plan_t *plan = calloc((size_t)(n ? n : 1), sizeof *plan);
    for (int i = 0; i < n; i++) {
        char buf[128];
        snprintf(buf, sizeof buf, "%s", argv[a + i]);
        char *at = strchr(buf, '@');
        if (at) { *at = 0; plan[i].at = strtoull(at + 1, NULL, 10); }
        char *dot = strchr(buf, '.');
        plan[i].machine = plan[i].event = -1;
        if (dot) {
            *dot = 0;
            if (!strcmp(buf, "device")) { plan[i].machine = 0; plan[i].event = lookup(device_events, dot + 1); }
            else if (!strcmp(buf, "sampler")) { plan[i].machine = 1; plan[i].event = lookup(sampler_events, dot + 1); }
            else if (!strcmp(buf, "logger")) { plan[i].machine = 2; plan[i].event = lookup(logger_events, dot + 1); }
            else if (!strcmp(buf, "sensor")) { plan[i].machine = 3; plan[i].event = lookup(sensor_events, dot + 1); }
        }
        if (plan[i].event < 0) {
            fprintf(stderr, "%s: not machine.EVENT for a machine and event in this system\n", argv[a + i]);
            return 2;
        }
    }

    logger_system_boards_t boards;
    boards.device = device_fake_hal(&device_probe);
    boards.sampler = sampler_fake_hal(&sampler_probe);
    boards.logger = logger_fake_hal(&logger_probe);
    boards.sensor = sensor_fake_hal(&sensor_probe);
    FILE *trace = NULL;
    if (trace_path) {
        trace = fopen(trace_path, "wb");
        if (!trace) { perror(trace_path); return 1; }
        uint8_t h[LOGGER_SYSTEM_TRACE_HEADER_SIZE];
        fwrite(h, 1, logger_system_trace_header(h), trace);
    }
    logger_system_init(&sys, &boards);
    if (trace) logger_system_set_trace(&sys, trace_sink, trace);
    drain(0);
    for (uint64_t t = 0; t <= run_ms; t += 10) {
        device_probe.now_ms = t;
        sampler_probe.now_ms = t;
        logger_probe.now_ms = t;
        sensor_probe.now_ms = t;
        for (int i = 0; i < n; i++)
            if (!plan[i].sent && plan[i].at <= t) { plan[i].sent = 1; post(&plan[i]); }
        logger_system_step_all(&sys);
        drain(t);
    }
    printf("after %llu ms:\n", (unsigned long long)run_ms);
    for (int i = 0; i < LOGGER_SYSTEM_DEVICE_INSTANCES; i++) printf("  device[%d]  %s\n", i, device_state_id(sys.device[i].state));
    for (int i = 0; i < LOGGER_SYSTEM_SAMPLER_INSTANCES; i++) printf("  sampler[%d]  %s\n", i, sampler_state_id(sys.sampler[i].state));
    for (int i = 0; i < LOGGER_SYSTEM_LOGGER_INSTANCES; i++) printf("  logger[%d]  %s\n", i, logger_state_id(sys.logger[i].state));
    for (int i = 0; i < LOGGER_SYSTEM_SENSOR_INSTANCES; i++) printf("  sensor[%d]  %s\n", i, sensor_state_id(sys.sensor[i].state));
    if (trace) fclose(trace);
    free(plan);
    return 0;
}
